USE DATABASE TRUSTED_AI_GOVERNANCE;
SELECT DQ_SCENARIO_ID,COUNT(*) OBSERVED,IFF(COUNT(*)>=1,'PASS','FAIL') RESULT FROM SILVER_QUARANTINE.REJECTED_RECORD WHERE DQ_SCENARIO_ID IN ('DQ-01','DQ-02','DQ-03','DQ-04','DQ-05','DQ-06','DQ-07','DQ-08') GROUP BY DQ_SCENARIO_ID ORDER BY 1;
SELECT 'NEGATIVE_ANCHORS_NOT_ADMITTED',COUNT(*),0,IFF(COUNT(*)=0,'PASS','FAIL') FROM (SELECT PAYMENT_ID ID FROM SILVER.PAYMENT WHERE PAYMENT_ID IN ('PAY_DQ_MISSING_CUSTOMER_001','PAY_DQ_CURRENCY_001','PAY_DQ_NEGATIVE_001','PAY_DQ_DUP_001') UNION ALL SELECT EXCEPTION_ID FROM SILVER.PAYMENT_EXCEPTION WHERE EXCEPTION_ID IN ('EXC_DQ_TIMESTAMP_001','EXC_DQ_REASON_001','EXC_DQ_EXPIRED_REF_001') UNION ALL SELECT SLA_EVENT_ID FROM SILVER.SLA_EVENT WHERE SLA_EVENT_ID='SLA_DQ_DUE_001');
SELECT 'POSITIVE_ANCHORS_ADMITTED',COUNT(*),4,IFF(COUNT(*)=4,'PASS','FAIL') FROM (SELECT CUSTOMER_ID FROM SILVER.CUSTOMER WHERE CUSTOMER_ID='CUST_DEMO_001' UNION ALL SELECT EXCEPTION_ID FROM SILVER.PAYMENT_EXCEPTION WHERE EXCEPTION_ID='EXC_DEMO_001' UNION ALL SELECT SLA_EVENT_ID FROM SILVER.SLA_EVENT WHERE SLA_EVENT_ID='SLA_DEMO_BREACH_001' UNION ALL SELECT OPERATIONS_USER_ID FROM SILVER.OPERATIONS_USER WHERE OPERATIONS_USER_ID='USER_SYN_001_MGR');
